import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.DDcl5AtZ.js";const u=JSON.parse('{"title":"Repository Maintainers","description":"","frontmatter":{},"headers":[],"relativePath":"maintainer/ci-cd-secrets-setup.md","filePath":"maintainer/ci-cd-secrets-setup.md"}'),n={name:"maintainer/ci-cd-secrets-setup.md"};function o(r,e,l,c,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="repository-maintainers" tabindex="-1">Repository Maintainers <a class="header-anchor" href="#repository-maintainers" aria-label="Permalink to &quot;Repository Maintainers&quot;">​</a></h1><p>Maintainers own the Ansible playbook, variable schema, GitHub Actions workflows, and documentation site.</p><h2 id="pull-request-and-release-checks" tabindex="-1">Pull request and release checks <a class="header-anchor" href="#pull-request-and-release-checks" aria-label="Permalink to &quot;Pull request and release checks&quot;">​</a></h2><p>The workflows in <code>.github/workflows/</code> call the reusable workflows from <code>gha-commit</code>, <code>gha-ansible</code>, and <code>gha-docs</code>:</p><ul><li>Pull requests validate the Conventional Commit message, lint and syntax check Ansible, validate <code>host_vars/</code>, and publish a documentation preview for same-repository pull requests.</li><li>Pushes to <code>master</code> run the same checks. Once they pass, the workflows update the latest docs, create a semantic version tag when the commit message calls for one, and publish tagged docs when a tag was created.</li></ul><p>The current Ansible checks do not connect to a Kubernetes cluster. No <code>kubeconfig</code> or provider credentials are required by these checks. GitHub Pages publishing requires Pages to be configured for this repository and the workflow permissions declared in the workflow files.</p><p>Commit headers must follow the supported Conventional Commit format, such as <code>feat(namespace): support a new option</code> or <code>fix: correct validation</code>. See <a href="https://ssongin.github.io/gha-commit/validation" target="_blank" rel="noreferrer"><code>gha-commit</code> validation guidance</a> and <a href="./../versioning.html">versioning</a> for accepted types and release behavior.</p><h2 id="maintain-the-host-variable-schema" tabindex="-1">Maintain the host-variable schema <a class="header-anchor" href="#maintain-the-host-variable-schema" aria-label="Permalink to &quot;Maintain the host-variable schema&quot;">​</a></h2><p>Update <code>schemas/namespace-schema.json</code> when the shape of the variables consumed by <code>apply.yml</code> changes. Keep the schema aligned with the role inputs and <code>host_vars/sample.yaml</code>. The <code>gha-ansible</code> workflow checks all YAML files in <code>host_vars/</code> against it on pull requests and pushes to <code>master</code>.</p><p>When adding an Ansible dependency, update <code>requirements.yml</code>. The CI workflow installs that Galaxy requirements file before checking <code>apply.yml</code>.</p><p>The <code>.ansible-lint</code> configuration skips the role-name and variable-name conventions because existing role paths and host-variable keys are consumed throughout the project. Keep those names consistent when adding or changing configuration.</p><h2 id="build-the-documentation-locally" tabindex="-1">Build the documentation locally <a class="header-anchor" href="#build-the-documentation-locally" aria-label="Permalink to &quot;Build the documentation locally&quot;">​</a></h2><p>Requirements: Node.js 22 and npm.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>Build the static site before merging documentation changes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>The version selector is implemented in <code>docs/.vitepress/theme/VersionSelector.vue</code> and reads the version manifest generated by <code>gha-docs</code> from the published Pages site.</p>`,17)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
